∃ S : Set ℝ, S = {c : ℝ | c > 0 ∧ 


    (∀ x : ℝ, (deriv (fun t => t^3 - c*t)) x = 0 → 
      ∃ h : ℝ, 
        let curvature_radius := (1 + (deriv (fun t => t^3 - c*t)) x ^ 2) ^ (-(1/2 : ℝ))
        let curvature_center := (x - (deriv (fun t => t^3 - c*t)) x / (1 + (deriv (fun t => t^3 - c*t)) x ^ 2), 0)
        curvature_center.2 = 0) ∧


    (let f : ℕ → ℕ := fun n => (n * (n + 1) * (n + 2)) % p
     let range_f : Finset ℕ := (Finset.range p).image f
     range_f.card = p - 1)}

∃ (A B : ℕ), 
  let α := Real.arccos (3/5)
  let β := Real.arcsin (3/5)
  let f := fun x : ℝ => (∑' n : ℕ, ∑' m : ℕ, 
    (Real.cos (α * n + β * m)) / (2^n * 3^m) * 
    ((4 + 3 * x^3) / (x * ((2 + x^5)^2)^(1/3 : ℝ)))) 
  Nat.gcd A B = 1 ∧ A > 0 ∧ B > 0 ∧
  deriv f 1 = (A : ℝ) / (B : ℝ) ∧
  1000 * A + B = 123456789

{(p₁, p₂) : ℕ × ℕ | Nat.Prime p₁ ∧ Nat.Prime p₂ ∧ p₁ ≤ p₂ ∧ 
   (2 * p₁ + p₂)^2 + (p₁ + 2 * p₂)^2 = 100000} = 
  {(3, 101), (101, 3)}
